import { describe, expect, it } from 'vitest'
import {
  escapeForStringLiteral,
  injectIntoKitModule,
  isKitTemplateModule,
  injectionSrc,
  injectionTag,
  usesSvelteKit,
} from '../src/plugin/inject.js'

/** Shape generated by SvelteKit 3.1 (`fixtures/kit/.svelte-kit/generated/dev/server.js`). */
const KIT_3 = `const server = {
	templates: {
		app: ({ head, body, assets, nonce, env }) => "<!doctype html>\\n<html lang=\\"en\\">\\n  <head>\\n    " + head + "\\n  </head>\\n  <body data-sveltekit-preload-data=\\"hover\\">\\n    <div style=\\"display: contents\\">" + body + "</div>\\n  </body>\\n</html>\\n",
		error: ({ status, message }) => "<!doctype html>\\n<html><body>" + message + "</body></html>"
	}
};
`

/** Shape documented for SvelteKit 2 (`generated/server/internal.js`). */
const KIT_2 = `export const templates = {};
templates.app = ({ head, body, assets, nonce }) => "<!doctype html>\\n<html>\\n<head>" + head + "</head>\\n<body>" + body + "</body>\\n</html>";
templates.error = ({ status, message }) => "<!doctype html>\\n<html><body>" + message + "</body></html>";
`

const TAG = '<script type="module" src="/@id/virtual:sphere/overlay"></script>'

describe('injectIntoKitModule', () => {
  it('inserts the tag before </body> inside the template literal (Kit 3)', () => {
    const result = injectIntoKitModule(KIT_3, TAG)

    expect(result.injected).toBe(true)
    expect(result.code).toContain(escapeForStringLiteral(TAG))
    expect(result.code.indexOf(escapeForStringLiteral(TAG))).toBeLessThan(
      result.code.indexOf('</body>'),
    )
    // The error template has its own </body> and must be untouched: exactly one insertion.
    expect(result.code.split(escapeForStringLiteral(TAG))).toHaveLength(2)
  })

  it('inserts into the assignment form (Kit 2)', () => {
    const result = injectIntoKitModule(KIT_2, TAG)

    expect(result.injected).toBe(true)
    expect(result.code.indexOf(escapeForStringLiteral(TAG))).toBeLessThan(
      result.code.indexOf('</body>'),
    )
  })

  it('escapes the tag once, so the emitted HTML keeps its quotes', () => {
    const result = injectIntoKitModule(KIT_3, TAG)
    expect(result.code).toContain('type=\\"module\\"')
    expect(result.code).not.toContain('type=\\\\"module')
  })

  it('is idempotent: HMR re-transforms the same module', () => {
    const once = injectIntoKitModule(KIT_3, TAG)
    const twice = injectIntoKitModule(once.code, TAG)

    expect(twice.injected).toBe(false)
    expect(twice.code).toBe(once.code)
  })

  it('returns the module unchanged when the shape is not recognised', () => {
    expect(injectIntoKitModule('export const nothing = 1\n', TAG)).toEqual({
      code: 'export const nothing = 1\n',
      injected: false,
    })
    expect(injectIntoKitModule(KIT_3.replaceAll('</body>', ''), TAG).injected).toBe(false)
    expect(injectIntoKitModule(KIT_3.replace('templates', 'templatez'), TAG).injected).toBe(false)
  })

  it('refuses to insert when </body> is outside the template literal', () => {
    const broken = `const server = { templates: { app: ({ head }) => "<!doctype html>" + head } };\nconst body = "</body>";\n`
    expect(injectIntoKitModule(broken, TAG).injected).toBe(false)
  })
})

describe('escapeForStringLiteral', () => {
  it('escapes quotes and backslashes, keeping the tag valid inside a literal', () => {
    expect(escapeForStringLiteral(TAG)).toBe(
      '<script type=\\"module\\" src=\\"/@id/virtual:sphere/overlay\\"></script>',
    )
    expect(escapeForStringLiteral('a\\b')).toBe('a\\\\b')
  })
})

describe('injectionSrc', () => {
  it('leaves the base to Vite for HTML tags and adds it for raw insertion', () => {
    expect(injectionSrc('/app/', { absolute: false })).toBe('/@id/virtual:sphere/overlay')
    expect(injectionSrc('/app/', { absolute: true })).toBe('/app/@id/virtual:sphere/overlay')
    expect(injectionTag('/', { absolute: true })).toBe(
      '<script type="module" src="/@id/virtual:sphere/overlay"></script>',
    )
  })
})

describe('usesSvelteKit', () => {
  it('looks for SvelteKit plugin names, wherever they sit in the array', () => {
    expect(usesSvelteKit(['vite-plugin-sveltekit-setup'])).toBe(false)
    expect(usesSvelteKit([{ name: 'vite-plugin-sveltekit-setup' }])).toBe(true)
    expect(
      usesSvelteKit([
        { name: 'vite-plugin-svelte' },
        { name: 'vite-plugin-sveltekit-resolve-root' },
      ]),
    ).toBe(true)
    expect(usesSvelteKit([{ name: 'vite-plugin-svelte' }])).toBe(false)
    expect(usesSvelteKit([])).toBe(false)
    expect(usesSvelteKit(undefined)).toBe(false)
    expect(usesSvelteKit([null, 42, {}])).toBe(false)
    // `sveltekit()` returns an array of plugins, so the user's `plugins` is nested.
    expect(
      usesSvelteKit([[{ name: 'vite-plugin-svelte' }], [{ name: 'vite-plugin-sveltekit-setup' }]]),
    ).toBe(true)
  })
})

describe('isKitTemplateModule', () => {
  it('matches the two generated modules and nothing else', () => {
    expect(isKitTemplateModule('/app/.svelte-kit/generated/server/internal.js')).toBe(true)
    expect(isKitTemplateModule('/app/.svelte-kit/generated/dev/server.js?v=1')).toBe(true)
    expect(isKitTemplateModule('/app/.svelte-kit/generated/dev/client/app.js')).toBe(false)
    expect(isKitTemplateModule('/app/src/routes/+page.svelte')).toBe(false)
  })
})
